dashboard.definition:
{
  "title": "9 · AI Observability & Governance",
  "description": "See AI usage, cost, latency and guardrail findings in one place.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "bg_001": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "bg_002": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#16A3B0",
        "strokeColor": "#16A3B0",
        "strokeWidth": 1,
        "rx": 3
      }
    },
    "md_003": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "USE CASE 9 OF 9  ·  SPITAL AARWALD  ·  SAMPLE DATA",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "md_004": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# AI Observability & Governance",
        "fontColor": "#E6EDF3"
      }
    },
    "md_005": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "What AI is used for, what it costs and what the guardrails catch — evidence to release the handbrake.",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 15
      }
    },
    "bg_006": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#11161D",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 8
      }
    },
    "md_007": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "WHAT WE HEARD",
        "fontColor": "#6E7681",
        "fontSize": "custom",
        "customFontSize": 11
      }
    },
    "md_008": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "*“AI Observability ist sehr interessant, GL hat da zur Zeit aber etwas die Handbremse drauf, aufgrund Unsicherheit.”*",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_009": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_010": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "4 applications · 1,180 users",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_011"
      },
      "title": "AI requests today"
    },
    "bg_012": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_013": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": "CHF ",
        "unitPosition": "before",
        "underLabel": "budget CHF 7,500",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_014"
