    "bg_024": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_025": {
      "type": "splunk.pie",
      "options": {
        "backgroundColor": "#161B22",
        "showDonutHole": true,
        "labelDisplay": "valuesAndPercentage",
        "legendDisplay": "off",
        "seriesColors": [
          "#3987E5",
          "#D95926",
          "#199E70",
          "#C98500",
          "#D55181",
          "#008300",
