        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_028": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#161B22",
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "When": {
            "width": 90
          },
          "Application": {
            "width": 185
          },
          "User group": {
            "width": 100
          },
          "Finding": {
            "width": 220
          },
          "Action": {
            "width": 90,
            "rowBackgroundColors": "> table | seriesByName(\"Action\") | matchValue(c0Bg)",
            "rowColors": "> table | seriesByName(\"Action\") | matchValue(c0Fg)"
          },
          "Model": {
            "width": 165
          }
        }
      },
      "dataSources": {
        "primary": "ds_029"
      },
      "title": "Latest guardrail events",
      "context": {
        "c0Bg": [
          {
            "match": "Blocked",
            "value": "#3F1D20"
          },
          {
            "match": "Redacted",
            "value": "#3A2E12"
          },
          {
            "match": "Flagged",
            "value": "#1F242C"
          }
        ],
        "c0Fg": [
          {
            "match": "Blocked",
            "value": "#FF8A80"
          },
          {
            "match": "Redacted",
            "value": "#E3B341"
          },
          {
            "match": "Flagged",
            "value": "#9AA4B2"
          }
