  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"cyc,slot,n\n0,0,2574\n0,1,6882\n0,2,6773\n0,3,6641\n0,4,6690\n0,5,6506\n0,6,2446\n1,0,2614\n1,1,6974\n1,2,6582\n1,3,6842\n1,4,7067\n1,5,6541\n1,6,2488\n2,0,2273\n2,1,6962\n2,2,6932\n2,3,6660\n2,4,6672\n2,5,6743\n2,6,2152\n3,0,2213\n3,1,6635\n3,2,7018\n3,3,6564\n3,4,6892\n3,5,6604\n3,6,2398\n4,0,2309\n4,1,6729\n4,2,6931\n4,3,6589\n4,4,6773\n4,5,6714\n4,6,2506\n5,0,2387\n5,1,6849\n5,2,6544\n5,3,6704\n5,4,6505\n5,5,6921\n5,6,2156\"\n| eval _time=relative_time(now(), \"@w0\") + slot*86400 - cyc*604800\n| where _time<=now() AND _time>now()-2592000\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,chf\n22,242\n21,424\n20,669\n19,861\n18,1053\n17,1261\n16,1490\n15,1717\n14,1952\n13,2178\n12,2389\n11,2557\n10,2803\n9,2980\n8,3202\n7,3458\n6,3662\n5,3852\n4,4112\n3,4324\n2,4497\n1,4721\n0,4915\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time chf",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"ago,s\n23,2.64\n22,2.18\n21,2.65\n20,2.4\n19,2.44\n18,2.42\n17,2.22\n16,2.14\n15,2.22\n14,2.56\n13,3.42\n12,2.19\n11,2.66\n10,2.53\n9,2.12\n8,2.26\n7,2.51\n6,2.61\n5,2.55\n4,2.54\n3,2.45\n2,2.12\n1,2.62\n0,2.34\"\n| eval _time=relative_time(now(), \"@h\") - ago*3600\n| sort 0 _time\n| table _time s",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_020": {
      "type": "ds.search",
      "name": "ds_020",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n13,31\n12,29\n11,27\n10,26\n9,24\n8,23\n7,22\n6,21\n5,20\n4,19\n3,18\n2,17\n1,18\n0,17\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_023": {
      "type": "ds.search",
      "name": "ds_023",
      "options": {
        "query": "| makeresults format=csv data=\"cyc,slot,Radiology report assistant,Clinical documentation,IT helpdesk bot,Translation\n0,0,1020,495,240,185\n0,1,2609,1421,834,426\n0,2,2696,1582,806,455\n0,3,2624,1586,751,424\n0,4,2508,1559,786,437\n0,5,2533,1512,765,453\n0,6,979,439,268,184\n1,0,873,435,275,121\n1,1,2534,1466,796,414\n1,2,2563,1432,779,460\n1,3,2552,1436,806,387\n1,4,2486,1507,839,451\n1,5,2686,1519,803,424\n1,6,970,498,292,115\n2,0,897,600,249,119\n2,1,2674,1512,805,427\n2,2,2700,1553,787,397\n2,3,2650,1484,761,413\n2,4,2487,1422,860,402\n2,5,2547,1452,755,457\n2,6,826,438,226,114\n3,0,904,488,320,156\n3,1,2555,1566,741,425\n3,2,2552,1446,801,451\n3,3,2551,1445,751,451\n3,4,2555,1588,755,388\n3,5,2587,1525,758,451\n3,6,984,533,295,128\n4,0,958,505,318,183\n4,1,2705,1565,803,424\n4,2,2505,1422,775,447\n4,3,2512,1454,842,460\n4,4,2690,1431,760,408\n4,5,2699,1413,765,402\n4,6,910,551,295,178\n5,0,928,534,230,129\n5,1,2620,1533,815,413\n5,2,2617,1427,860,383\n5,3,2628,1559,853,435\n5,4,2619,1489,807,447\n5,5,2617,1574,856,388\n5,6,1013,599,293,176\"\n| eval _time=relative_time(now(), \"@w0\") + slot*86400 - cyc*604800\n| where _time<=now() AND _time>now()-2592000\n| sort 0 _time\n| eval \"Radiology report assistant\"=round('Radiology report assistant' + 900*(1-(now()-_time)/2592000), 1)\n| eval \"Clinical documentation\"=round('Clinical documentation' + 600*(1-(now()-_time)/2592000), 1)\n| table _time \"Radiology report assistant\" \"Clinical documentation\" \"IT helpdesk bot\" Translation",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_026": {
      "type": "ds.search",
      "name": "ds_026",
      "options": {
        "query": "| makeresults format=csv data=\"Finding,Count\nPatient data (PHI),41\nPersonal data (PII),27\nConfidential documents,12\nPrompt injection attempt,6\"\n| table Finding Count",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_029": {
      "type": "ds.search",
      "name": "ds_029",
      "options": {
        "query": "| makeresults format=csv data=\"When,Application,User group,Finding,Action,Model\n12,Clinical documentation,Nursing,Patient name + DOB in prompt,Redacted,GPT-4o (Azure CH)\n47,Translation,Admin staff,Insurance number,Redacted,GPT-4o mini (Azure CH)\n95,IT helpdesk bot,External,Prompt injection attempt,Blocked,GPT-4o mini (Azure CH)\n230,Radiology report assistant,Radiology,Report sent to non-CH endpoint,Blocked,Vendor model (EU)\n415,Clinical documentation,Physicians,Full discharge letter,Flagged,GPT-4o (Azure CH)\"\n| eval \"When\"=strftime(relative_time(now(), \"@m\") - 'When'*60, \"%a %H:%M\")\n| table When Application \"User group\" Finding Action Model",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_032": {
      "type": "ds.search",
      "name": "ds_032",
      "options": {
        "query": "| makeresults format=csv data=\"Model,CHF\nGPT-4o,2940\nLlama (on-prem),1090\nGPT-4o mini,610\nEmbeddings,180\"\n| table Model CHF",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    }
  },
